CustomCss:
body{letter-spacing:.15px}
h2{padding-bottom:8px;border-bottom:1px solid var(--b)}
.form,.sc,.ig,table{border-radius:14px}
.form,.sc{border:1px solid var(--b);box-shadow:0 1px 3px rgba(76,79,105,.05)}
.form:hover,.sc:hover{border-color:var(--a);box-shadow:0 4px 16px rgba(137,180,250,.14)}
.badge{border-radius:999px;padding:3px 10px;font-weight:600}
.chip{border-radius:999px}
.ni{border-radius:0 12px 12px 0;transition:background .15s ease,color .15s ease}
.ni:hover{background:var(--hover)}
.ni.active{background:rgba(137,180,250,.14);font-weight:600}
button.bp,button.bd,button.bw,button.bsm{border-radius:999px;font-weight:600;padding-left:18px;padding-right:18px;transition:transform .12s ease,box-shadow .12s ease}
button.bp:hover,button.bd:hover,button.bw:hover{transform:translateY(-1px);box-shadow:0 4px 12px rgba(76,79,105,.18)}
input,select,textarea{border-radius:10px}
input:focus,select:focus,textarea:focus{border-color:var(--a);box-shadow:0 0 0 3px rgba(137,180,250,.18)}
th{background:var(--s);font-weight:600}
